<template><el-button link type="primary" @click="open">服务流程</el-button><el-dialog v-model="visible" title="工作室订单履约" width="min(600px,94vw)" append-to-body><el-alert title="工作室统一收款，摄影师提供服务；交付后由工作室登记内部结算。" type="info" :closable="false"/><p>当前阶段：{{labels[flow.stage]||'待确认套餐'}}</p><el-form label-position="top"><el-form-item label="服务套餐"><el-input v-model="form.packageName" :disabled="!!flow.stage && flow.stage!=='pending'" maxlength="200"/></el-form-item><el-form-item label="服务内容（含拍摄时长、精修数量、交付约定等）"><el-input v-model="form.serviceContent" type="textarea" :rows="4" :disabled="!!flow.stage && flow.stage!=='pending'" maxlength="2000"/></el-form-item><p>预约金额：¥ {{row.yuyuejiage}}（使用预约时记录的价格）</p><el-form-item v-if="admin && flow.stage==='shot'" label="照片交付链接"><el-input v-model="form.deliveryUrl" placeholder="https://..."/></el-form-item><el-form-item v-if="admin && flow.stage==='delivered'" label="内部结算说明（仅管理员可见）"><el-input v-model="form.settlementNote" type="textarea" placeholder="登记工资或提成核对依据" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="visible=false">关闭</el-button><el-button v-if="!flow.stage || flow.stage==='pending'" type="primary" :loading="busy" @click="save('confirm')">确认档期与服务</el-button><el-button v-if="flow.stage==='confirmed' && row.ispay==='已支付'" type="primary" :loading="busy" @click="save('shoot')">登记拍摄完成</el-button><el-button v-if="admin && flow.stage==='shot'" type="primary" :loading="busy" @click="save('deliver')">工作室交付照片</el-button><el-button v-if="admin && flow.stage==='delivered'" type="primary" :loading="busy" @click="save('settle')">登记内部结算</el-button></template></el-dialog></template>
<script setup>
import {ref,getCurrentInstance} from 'vue'
const props=defineProps({row:Object}),emit=defineEmits(['changed']),ctx=getCurrentInstance().appContext.config.globalProperties,admin=localStorage.getItem('sessionTable')==='users'
const visible=ref(false),busy=ref(false),flow=ref({}),form=ref({}),labels={pending:'待确认套餐',confirmed:'已确认，等待付款或拍摄',shot:'拍摄完成',delivered:'工作室已交付',settled:'内部结算已登记'}
async function open(){try{const res=await ctx.$http.get('sheyingshiyuyue/workflow/'+props.row.id);flow.value=res.data.data;form.value={packageName:flow.value.package_name||'',serviceContent:flow.value.service_content||'',deliveryUrl:flow.value.delivery_url||'',settlementNote:flow.value.settlement_note||''};visible.value=true}catch{ctx.$toolUtil.message('订单流程加载失败','error')}}
async function save(action){if(busy.value)return;busy.value=true;try{await ctx.$http.post('sheyingshiyuyue/workflow/'+props.row.id+'/'+action,form.value);emit('changed');visible.value=false;ctx.$toolUtil.message('订单流程已更新','success')}catch{ctx.$toolUtil.message('操作未完成，请检查订单状态和填写内容','error')}finally{busy.value=false}}
</script>
